const $=id=>document.getElementById(id),money=n=>`₹${Math.round(n).toLocaleString('en-IN')}`,finite=(...v)=>v.every(Number.isFinite),MAX=1e12,SAFE=Number.MAX_SAFE_INTEGER;
const tools={sip:['SIP Goal Planner',['Target amount','Annual rate (%)','Years'],[5000000,12,10]],emi:['Home Loan EMI',['Loan amount','Annual rate (%)','Years'],[5000000,8.5,20]],inflation:['Inflation Impact',["Today's cost",'Annual inflation rate (%)','Years'],[50000,6,10]],step:['Step-up SIP',['Starting monthly SIP','Annual step-up (%)','Annual return (%)','Whole years'],[5000,10,12,15]],cagr:['CAGR Calculator',['Initial value','Final value','Years'],[100000,185000,5]],growth:['Compound Growth',['Starting lump sum','Monthly contribution','Annual rate (%)','Years'],[100000,5000,10,10]],card:['Credit-card Payoff',['Balance','Annual rate (%)','Fixed monthly payment'],[100000,36,6000]],emergency:['Emergency Coverage',['Cash and bank','Fixed deposits','Other accessible','Monthly outgoings'],[60000,90000,0,30000]],goal:['Goal contribution gap',['Target','Current amount','Planned monthly','Annual rate (%)','Years'],[2000000,300000,10000,10,8]]};
let state={screen:'tools',id:null,draft:[],result:null,offline:false,failed:false,permission:true,cap:false};
function strict(x){const s=String(x).trim();if(!/^(?:\d+(?:\.\d+)?|\d{1,3}(?:,\d{2})+(?:,\d{3})(?:\.\d+)?|\d{1,3}(?:,\d{3})+(?:\.\d+)?)$/.test(s))return NaN;return Number(s.replaceAll(',',''))}
function calc(id,v){if(!finite(...v))return {error:'Enter complete ordinary finite numbers. Partial, grouped incorrectly or exponential values are not accepted.'};if(v.some(x=>Math.abs(x)>MAX))return {error:'An input exceeds the supported ₹1 lakh crore boundary.'};let primary='',secondary='',formula='',omit='Tax, fees, institution-specific rounding and changing real-world conditions are omitted.';
if(id==='sip'){let[t,r,y]=v,n=Math.round(y*12);if(!(t>0&&r>=0&&r<=1000&&n>=1&&n<=2400))return{error:'Use a positive target, 0% to 1,000% rate and 1 to 2,400 modeled months.'};let m=r===0?t/n:t*(r/1200)/(Math.pow(1+r/1200,n)-1);primary=money(m);formula='Inverse ordinary annuity; zero rate uses target ÷ months. Contributions land at month end.'}
if(id==='emi'){let[p,r,y]=v,n=Math.round(y*12);if(!(p>0&&r>=0&&r<=1000&&n>=1&&n<=600))return{error:'Use a positive principal, 0% to 1,000% rate and 1 to 600 modeled months.'};let q=r/1200,g=Math.pow(1+q,n),e=q===0?p/n:p*q*g/(g-1);primary=money(e);secondary=`Total interest ${money(e*n-p)}`;formula='Fixed monthly amortisation; zero rate uses principal ÷ months.'}
if(id==='inflation'){let[p,r,y]=v;if(!(p>0&&r>=-100&&r<=1000&&y>=0&&y<=200))return{error:'Use a positive cost, -100% to 1,000% rate and 0 to 200 years.'};primary=money(p*Math.pow(1+r/100,y));formula='Present cost × (1 + entered annual rate)^years.'}
if(id==='step'){let[m,s,r,y]=v;if(!(m>0&&s>=0&&s<=1000&&r>=0&&r<=1000&&Number.isInteger(y)&&y>=1&&y<=200))return{error:'Use a positive SIP, 0% to 1,000% rates and 1 to 200 whole years.'};let b=0,invest=0;for(let k=0;k<y*12;k++){b=b*(1+r/1200)+m*Math.pow(1+s/100,Math.floor(k/12));invest+=m*Math.pow(1+s/100,Math.floor(k/12))}primary=money(b);secondary=`Total contributed ${money(invest)}`;formula='Month-end contributions; step changes at each new 12-month block.'}
if(id==='cagr'){let[a,b,y]=v;if(!(a>0&&b>0&&y>0&&y<=200))return{error:'Use positive values and a horizon above 0 and no more than 200 years.'};primary=`${((Math.pow(b/a,1/y)-1)*100).toFixed(2)}%`;formula='(final ÷ initial)^(1 ÷ years) - 1. Historical smoothing only.'}
if(id==='growth'){let[l,m,r,y]=v,n=Math.round(y*12);if(!(l>=0&&m>=0&&(l||m)&&r>=0&&r<=1000&&n>=1&&n<=2400))return{error:'Use non-negative amounts, 0% to 1,000% rate and 1 to 2,400 months.'};let q=r/1200,g=Math.pow(1+q,n),end=q===0?l+m*n:l*g+m*(g-1)/q;primary=money(end);secondary=`Total contributed ${money(l+m*n)}`;formula='Monthly compounding with month-end contributions.'}
if(id==='card'){let[b,r,p]=v;if(!(b>0&&r>=0&&r<=1000&&p>0))return{error:'Use positive balance/payment and a 0% to 1,000% rate.'};let q=r/1200;if(b*q>=p)return{error:'The first month interest is at least the fixed payment, so no payoff result is shown.'};let total=0,interest=0,last=0,n=0;for(;n<1200&&b>1e-8;n++){let i=b*q,d=b+i,lastPay=Math.min(p,d);interest+=i;total+=lastPay;b=d-lastPay;last=lastPay}if(b>1e-8)return{error:'The balance does not reach zero within 1,200 months.'};primary=`${n} months`;secondary=`Total interest ${money(interest)}; final payment ${money(last)}`;formula='Monthly interest first, then fixed payment.'}
if(id==='emergency'){let[c,f,o,m]=v;if(!(c>=0&&f>=0&&o>=0&&m>0))return{error:'Balances must be non-negative and monthly outgoings positive.'};primary=`${((c+f+o)/m).toFixed(1)} months`;secondary=`Included accessible balances ${money(c+f+o)}`;formula='Included accessible balances ÷ monthly outgoings.'}
if(id==='goal'){let[t,c,p,r,y]=v,n=Math.round(y*12);if(!(t>0&&c>=0&&p>=0&&r>=0&&r<=1000&&n>=1&&n<=2400))return{error:'Use supported non-negative inputs and 1 to 2,400 months.'};let q=r/1200,g=Math.pow(1+q,n),need=Math.max(0,t-c*g),modeled=q===0?need/n:need*q/(g-1),diff=p-modeled;primary=money(modeled);secondary=`Planned minus modeled ${money(diff)}`;formula='Current amount compounds; inverse month-end contribution closes the remaining modeled target.'}
if(!finite(Number(primary.replace?.(/[^0-9.-]/g,'')))||[primary,secondary].join('').includes('Infinity'))return{error:'This combination exceeds the safe output range.'};return{primary,secondary,formula,omit}}
function render(){const c=$('app-content');$('back').hidden=state.screen==='tools';$('close').hidden=state.screen==='tools';if(state.screen==='tools'){c.innerHTML=`<h1>Calculators</h1><p class="lede">Transparent arithmetic from assumptions you choose.</p><div class="tool-list">${Object.entries(tools).map(([id,t])=>`<button class="tool-card" data-tool="${id}"><strong>${t[0]}</strong><span class="meta">Open and enter your own assumptions</span></button>`).join('')}</div>`}else{const t=tools[state.id];c.innerHTML=`<h1>${t[0]}</h1><p class="lede">You author every assumption. This calculator does not choose an action.</p>${state.failed&&state.id==='emergency'?'<section class="error-card" role="alert">Recorded sources could not load. Manual entry remains available. <button data-retry>Retry source</button></section>':''}<div class="field-list">${t[1].map((x,i)=>`<label class="form-field">${x}<input data-i="${i}" inputmode="decimal" value="${state.draft[i]??''}"></label>`).join('')}</div><div class="actions"><button class="primary" data-run>Calculate</button><button data-reset>Reset</button></div>${state.result?resultHtml(state.result):''}`};bind()}
function resultHtml(r){if(r.error)return`<section class="error-card" role="alert"><h2 tabindex="-1">Cannot calculate</h2><p>${r.error}</p></section>`;return`<section id="result" tabindex="-1"><h2 class="section-heading">Result for these inputs</h2><div class="result-card"><div class="result-value">${r.primary}</div><p>${r.secondary}</p></div><h2>Inputs used</h2><p>${state.draft.join(' | ')}</p><p class="formula">${r.formula}</p><p class="limits">${r.omit} Conditional arithmetic, not a forecast or recommendation.</p><button data-arya>Explore the mechanism with Arya</button></section>`}
function bind(){document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{state.screen='tool';state.id=b.dataset.tool;state.draft=[...tools[state.id][2]];state.result=null;render()});document.querySelectorAll('[data-i]').forEach(i=>i.oninput=()=>{state.draft[+i.dataset.i]=i.value;if(state.result){state.result=null;render();log('Inputs changed. Prior result and handoff removed.')}});document.querySelector('[data-run]')?.addEventListener('click',()=>{state.result=calc(state.id,state.draft.map(strict));render();if(!state.result.error){$('announce').textContent=`Result: ${state.result.primary}`;$('result').focus();log(state.cap?'Result kept; progression cap simulated.':`calculator_completed spy: ${state.id}; no values recorded.`)}});document.querySelector('[data-reset]')?.addEventListener('click',resetTool);document.querySelector('[data-retry]')?.addEventListener('click',()=>{state.failed=false;render();log('Only failed source retried.')});document.querySelector('[data-arya]')?.addEventListener('click',()=>{ $('dialog-body').innerHTML=`<p>Calculator type: ${state.id}</p><p>Normalized inputs: ${state.draft.join('; ')}</p><p>Formula boundary: ${state.result.formula}</p><p>Omissions: ${state.result.omit}</p>`;$('dialog').showModal();$('dialog-title').focus()})}
function resetTool(){state.draft=state.id?[...tools[state.id][2]]:[];state.result=null;render();log('Draft, errors and result cleared.')}function log(x){$('log').textContent=x}$('back').onclick=$('close').onclick=$('tools').onclick=()=>{state.screen='tools';state.id=null;state.result=null;render()};
const states=Array.from({length:51},(_,i)=>`CA-${String(i+1).padStart(2,'0')}`);$('state').innerHTML='<option>Choose a canonical state</option>'+states.map(x=>`<option>${x}</option>`).join('');$('state').onchange=e=>{let n=+e.target.value.slice(3);state.screen='tool';state.id=['sip','emi','inflation','step','cagr','growth','card','emergency','goal'][(n-1)%9];state.draft=[...tools[state.id][2]];state.result=null;if([17,18,20,21,29].includes(n))state.draft[0]='1e309';if([24,25,26,27].includes(n))state.result=calc(state.id,state.draft.map(Number));if(n===30){state.result=calc(state.id,state.draft.map(Number));state.draft[0]='999';state.result=null}if(n===40)state.offline=true;if(n===42)state.permission=false;if(n===35)state.cap=true;render();log(`${e.target.value} fixture loaded.`)};document.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{if(b.dataset.f==='reset')Object.assign(state,{screen:'tools',id:null,draft:[],result:null,offline:false,failed:false,permission:true,cap:false});if(b.dataset.f==='offline')state.offline=!state.offline;if(b.dataset.f==='failure'){state.failed=true;state.screen='tool';state.id='emergency';state.draft=[...tools.emergency[2]]}if(b.dataset.f==='permission'){state.permission=false;state.draft=[];state.result=null}if(b.dataset.f==='switch'){state.draft=[];state.result=null;state.screen='tools'}if(b.dataset.f==='cap')state.cap=true;render();log(`Fixture ${b.dataset.f} applied.`)});render();
